const fs=require("fs");
const html=fs.readFileSync("/home/zmhel/gitrepos/learn-ai/eval01/runs/.gen-work/t21/game.html","utf8");
const full=html.split("<script>")[1].split("</script>")[0];
const cut=full.indexOf("   12. UI");
const src=full.slice(0,full.lastIndexOf("/* ==",cut));
global.document={querySelector:()=>({textContent:full})};
global.performance={now:()=>Date.now()};
global.innerWidth=1000;
fs.writeFileSync("/tmp/g.js",src+"\nmodule.exports={runTests,runBenchmark,stateHash,newGame,resolveTurn,greedyTurn,pop,housing,scoreOf};");
const G=require("/tmp/g.js");
const r=G.runTests();
let f=0;
for(const t of r){ if(!t.pass){f++;console.log("FAIL:",t.name,"|",t.detail);} }
console.log("TESTS passed",r.length-f,"/",r.length);
const t0=Date.now();
const A=G.runBenchmark(1337,200), B=G.runBenchmark(1337,200);
console.log("bench hash",G.stateHash(A),G.stateHash(B),"identical:",G.stateHash(A)===G.stateHash(B),"ms/run",(Date.now()-t0)/2);
console.log("turn",A.turn,"pop",G.pop(A),"beds",G.housing(A),"bld",Object.keys(A.b).length,"tech",Object.keys(A.tech).length,"score",G.scoreOf(A).total);
console.log("res",JSON.stringify(Object.fromEntries(Object.entries(A.res).map(([k,v])=>[k,Math.round(v)]))));
console.log("stats",JSON.stringify(A.stats));
// Can the greedy policy WIN at turn 60? (interactive end-checks on)
for (const seed of [1337,9001,4242,777]){
  const S=G.newGame(seed);
  for(let i=0;i<70 && !S.over;i++){ G.greedyTurn(S); G.resolveTurn(S,false); }
  console.log("seed",seed,"-> over:",S.over? (S.over.win?"WIN":"LOSS")+" @T"+S.turn+" pop"+G.pop(S) : "still running T"+S.turn+" pop"+G.pop(S));
}

